-- | A grammar is a map of rules and an entry rule.
data Grammar t a = Grammar {
    rules :: Map String (Rule t a),
    entry :: String
} deriving (Show)

-- | A rule is a list of productions.
newtype Rule t a = Rule {
    productions :: [Production t a]
} deriving (Show)

-- | A production is a semantic action and a list of symbols.
data Production t a = Production {
    action :: Maybe (a -> t -> a),
    symbols :: [Symbol t a]
} deriving (Show)

